    INSERT INTO mcqs (topic_id, question, options, correct_index, explanation) VALUES
    (v_topic_id, 'Which of the following is the PRIMARY responsibility of a medical surrogate?', '["To make the decision that is easiest for the hospital", "To act as the patient''s voice and represent their known wishes or values", "To decide based on their own personal religious beliefs", "To minimize the inheritance taxes for the family"]', 1, 'The surrogate''s role is to ensure the patient''s autonomy is respected even when the patient is unable to communicate.'),
    (v_topic_id, 'When applying the "Substituted Judgment" standard, what is the surrogate actually doing?', '["Substituting their own judgment for the doctor''s", "Making the choice they believe the patient would have made if they were currently competent and sitting in the room", "Choosing the most expensive treatment", "Following a strict legal checklist"]', 1, 'Substituted judgment is about fidelity to the patient''s specific identity and prior choices.'),
    (v_topic_id, 'A patient has three adult children who disagree on the plan of care. They are all of equal rank in the surrogate hierarchy. What is the BEST next step for the physician?', '["Follow the oldest child''s decision", "Hold a family meeting to facilitate consensus and involve the hospital ethics committee for mediation if needed", "Do whatever the doctor wants", "Pick the child who lives closest"]', 1, 'Consensus-building is the standard of care for intra-family disagreements. Ethics committees are valuable resources for mediation.'),
    (v_topic_id, 'The "Best Interest Standard" is considered a "Lower Tier" standard compared to Substituted Judgment because:', '["It is illegal", "It relies on the surrogate''s or society''s views of what is "good" rather than the patient''s own specific autonomous values", "It is too expensive", "None of the above"]', 1, 'Substituted judgment is preferred because it respects the patient''s individual autonomy; Best Interest is used only when the patient''s specific views are unknown.'),
    (v_topic_id, 'Which of the following describes a "Surrogate of Last Resort"?', '["The patient''s neighbor", "A public guardian, a court-appointed individual, or sometimes a physician committee in states with such laws", "The first person to answer the phone", "None of the above"]', 1, 'For "unrepresented" patients, many states have established mechanisms to provide a legal surrogate to prevent care from being paralyzed by lack of consent.'),
    (v_topic_id, 'Can a surrogate demand "Physician-Assisted Suicide" (PAS) for an incapacitated patient?', '["Yes, if they are the DPOA-HC", "No, PAS (in states where legal) requires the patient themselves to be competent and make a voluntary, repeated request", "Only if the patient has cancer", "None of the above"]', 1, 'PAS is an act of voluntary autonomy; a surrogate cannot "opt-in" to it for someone else.'),
    (v_topic_id, 'What is "Anticipatory Grief"?', '["Grief that happens after the funeral", "The mourning process that occurs before the actual death, often as the family watches a loved one decline", "Grief that never ends", "None of the above"]', 1, 'Anticipatory grief is common in families of patients with chronic, terminal illnesses.'),
    (v_topic_id, 'A surrogate asks the doctor to "Not tell the patient the diagnosis" (e.g., metastatic cancer). This is known as:', '["Therapeutic Privilege", "Non-disclosure or family-centered truth-telling", "Medical neglect", "Paternalism"]', 1, 'While common in some cultures, in the US, patients have a right to their medical information unless they have specifically asked NOT to know.'),
    (v_topic_id, 'A patient is incapacitated and the surrogate (wife) says, "I know he would want everything done," but the patient has a Living Will that says "No life support." Which should the physician prioritize?', '["The wife''s verbal statement", "The written Living Will (as it is direct evidence of the patient''s own prospective autonomy)", "The doctor''s own preference", "The children''s preference"]', 1, 'A clear, written advance directive from the patient is generally considered more authoritative than a surrogate''s potentially conflicted or emotional interpretation.'),
    (v_topic_id, 'Which of the following is a "Conflict of Interest" for a surrogate?', '["Loving the patient too much", "Being the primary beneficiary of the patient''s large life insurance policy", "Wanting the patient to live", "None of the above"]', 1, 'Financial incentives can cloud a surrogate''s judgment and may require additional ethics or legal scrutiny.'),
    (v_topic_id, 'In the context of the "Hierarchy of Surrogates," what is the status of a "Domestic Partner"?', '["They are never surrogates", "Many states now recognize domestic partners or "significant others" in the hierarchy, often on the same level as a spouse", "They are at the bottom of the list", "Only if they have a contract"]', 1, 'Legal recognition of non-marital partners in medical decision-making has expanded significantly, though it varies by state.'),
    (v_topic_id, 'A surrogate is making decisions that seem to "Directly harm" the patient and are clearly contrary to the patient''s known values. What is the physician''s duty?', '["Follow the surrogate anyway", "Challenge the surrogate''s authority through the ethics committee or legal system if they are failing their fiduciary duty to the patient", "Call the police", "None of the above"]', 1, 'Surrogate authority is not absolute; it is conditional on the surrogate acting in the patient''s best interests or known wishes.'),
    (v_topic_id, 'What is "Compassion Fatigue"?', '["Being too happy", "A state of emotional, physical, and mental exhaustion caused by the prolonged stress of caring for those in distress", "A type of heart failure", "None of the above"]', 1, 'Clinicians and caregivers in palliative care are at high risk for compassion fatigue/burnout.'),
    (v_topic_id, 'Which of the following is a "Cultural" consideration in surrogacy?', '["Some cultures believe the eldest son must make all decisions regardless of the spouse''s rank", "Some cultures prefer family-based consensus over individual autonomy", "Some cultures consider discussing death to be a "jinx"", "All of the above"]', 3, 'Cultural humility involves understanding that the "individual autonomy" model of the US is not universal.'),
    (v_topic_id, 'The "Cruzan v. Director, Missouri Department of Health" case was significant because:', '["It legalized abortion", "It affirmed that competent people have a right to refuse treatment and allowed states to require "clear and convincing evidence" for withdrawing support from incapacitated patients", "It created Medicare", "None of the above"]', 1, 'Nancy Cruzan''s case was the first "right-to-die" case to reach the US Supreme Court.'),
    (v_topic_id, 'A surrogate wants to withdraw a "Feeding Tube" from a patient in PVS. Is this legally permissible?', '["No, it''s starving the patient", "Yes, in most states, artificial nutrition and hydration are considered medical treatments that can be withdrawn like any other life support", "Only if the patient is a child", "None of the above"]', 1, 'The US Supreme Court and the AMA both consider feeding tubes to be medical interventions that can be legally and ethically withdrawn.'),
    (v_topic_id, 'What is the "DNR" vs "Comfort Care" distinction?', '["DNR means you get no care", "DNR only refers to resuscitation during an arrest; Comfort Care (or Hospice) is a comprehensive plan for overall symptom management", "They are the same thing", "DNR is for rich people"]', 1, 'A common mistake is assuming that "DNR" means "Do Not Treat." One can be a DNR but still want full treatment for pneumonia.'),
    (v_topic_id, 'A "Fiduciary Duty" means the surrogate must:', '["Pay for everything", "Act in the highest good of the patient and set aside their own personal interests", "Be related to the patient", "None of the above"]', 1, 'The surrogate is a "fiduciary" for the patient''s autonomy.'),
    (v_topic_id, 'Which of the following is TRUE about surrogacy for "Minors"?', '["Children never have a voice", "The "Rule of Assent" means that children should be involved in the discussion to a developmentally appropriate degree, even if the parents have the final legal authority", "Children can sign their own DNRs", "None of the above"]', 1, 'Respecting a child''s developing autonomy through assent is a core tenet of pediatric ethics.'),
    (v_topic_id, 'A "Healthcare Proxy" is different from a "Next of Kin" because:', '["One is family, one is a doctor", "A Proxy is specifically chosen by the patient; Next of Kin is determined by blood/legal relationship", "A Proxy has no power", "None of the above"]', 1, 'Choosing your own proxy allows you to pick the person you trust most, regardless of their family rank.'),
    (v_topic_id, 'What is the "Slow Code"?', '["A method of resuscitation for elderly people", "An unethical practice of performing CPR in a intentionally delayed or half-hearted manner to give the appearance of effort without expectation of success", "A way to save electricity", "None of the above"]', 1, 'Slow codes are widely condemned as deceptive and a violation of professional integrity; the correct approach is a clear "DNR" or a full resuscitation.'),
    (v_topic_id, 'A "Limited Code" might specify:', '["Resuscitate for only 5 minutes", "Chest compressions and medications are allowed, but no intubation", "Only the nurse can help", "None of the above"]', 1, 'Patients can "buffet" their code status, choosing specific interventions while refusing others.'),
    (v_topic_id, 'Which of the following is a common reason for surrogate "Guilt"?', '["Making a decision that leads to the death of a loved one, even if it is what the loved one wanted", "Spending too much of the patient''s money", "Not visiting enough", "None of the above"]', 1, 'Clinicians must provide emotional support and reassurance to surrogates making difficult EOL choices.'),
    (v_topic_id, 'The "Mature Minor" doctrine allows some minors to:', '["Drive a car", "Make their own medical decisions (including EOL care) if they are determined to have the maturity and understanding of an adult", "Buy alcohol", "None of the above"]', 1, 'This varies by state but is an important legal exception to parental authority.'),
    (v_topic_id, 'A surrogate is making a decision based on "Religious Revelation" (e.g., "God told me he will wake up tomorrow"). How should the physician respond?', '["Tell them they are crazy", "Respect the belief while continuing to provide clinical evidence and potentially involving a chaplain or the ethics committee for mediation", "Call the police", "Immediately stop all care"]', 1, 'Spiritual beliefs are powerful in EOL care; bridging the gap between faith and clinical reality requires great sensitivity.'),
    (v_topic_id, 'What is the "Surrogate-Physician Conflict"?', '["When they disagree on the prognosis", "When the surrogate wants care that the physician deems "medically inappropriate" or vice versa", "When they don''t like each other", "None of the above"]', 1, 'These conflicts are the most frequent reason for hospital ethics consultations.'),
    (v_topic_id, 'Which of the following is a "Legal Risk" for a surrogate?', '["None, surrogates are immune to all lawsuits", "They could be challenged if they are clearly acting in bad faith or against a valid written directive", "They have to pay the patient''s debt", "None of the above"]', 1, 'While protected when acting in good faith, bad faith actors can be removed by the court.'),
    (v_topic_id, 'A "De-escalation" of care refers to:', '["Stopping all medication", "The systematic removal of life-sustaining treatments that are no longer meeting the goals of care (e.g., stopping vasopressors)", "Moving the patient to a smaller room", "None of the above"]', 1, 'De-escalation is part of the transition to comfort-focused care.'),
    (v_topic_id, 'Which of the following describes "Substituted Judgment"?', '["The surrogate decides what they would want for themselves", "The surrogate decides what they believe the patient would want", "The doctor decides what is standard", "None of the above"]', 1, 'This is the most "patient-centered" way for a surrogate to act.'),
    (v_topic_id, 'A surrogate asks, "Can we just give him something to end it quickly?" This is:', '["Euthanasia (Active)", "Comfort care", "A request for PAS", "None of the above"]', 0, 'In the US, active euthanasia (a doctor administering a lethal injection) is illegal in all 50 states, even if requested by a surrogate.'),
    (v_topic_id, 'What is the role of "Medicaid" in long-term end-of-life care?', '["It pays for everything", "It is the primary payer for nursing home care in the US once a patient has "spent down" their assets", "It only pays for kids", "None of the above"]', 1, 'Understanding the financial landscape of EOL care is part of comprehensive palliative planning.'),
    (v_topic_id, 'A "POLST" form is different from a "DNR" because:', '["POLST is for everyone", "POLST covers a range of treatments (antibiotics, fluids, hospitalization) beyond just CPR", "DNR is only for doctors", "None of the above"]', 1, 'POLST provides a more granular treatment plan.'),
    (v_topic_id, 'Which of the following is a sign of "Burnout" in EOL clinicians?', '["Increased empathy", "Depersonalization (treating patients like objects) and a sense of low personal accomplishment", "Increased productivity", "None of the above"]', 1, 'Burnout is a major issue in high-acuity, high-mortality fields.'),
    (v_topic_id, 'What is "Moral Distress"?', '["When you don''t know the answer", "When a clinician knows the ethically correct action but is blocked by institutional or legal constraints from taking it", "When you feel guilty about a mistake", "None of the above"]', 1, 'Moral distress is common when clinicians feel they are providing "non-beneficial" or "harmful" life-prolonging care to terminal patients.'),
    (v_topic_id, 'A surrogate is "Estranged" from the patient but is still the legal next-of-kin. Should they make decisions?', '["Yes, legally", "No, if their estrangement means they don''t know the patient''s wishes or have a conflict of interest, the next person in line may be more appropriate", "The doctor decides", "None of the above"]', 1, 'Legality and ethics sometimes clash; an estranged spouse who hasn''t seen the patient in 20 years might not be the best surrogate.'),
    (v_topic_id, 'Which of the following is a "Communication Strategy" for difficult surrogates?', '["Avoid them", "The "Ask-Tell-Ask" method to ensure they understand the clinical information before proceeding", "Be aggressive", "None of the above"]', 1, 'Ask-Tell-Ask helps align the surrogate''s perception with reality.'),
    (v_topic_id, 'A patient is a "DNR/DNI" but the surrogate demands they be intubated. What should the physician do?', '["Intubate immediately", "Explain the patient''s prior directive and attempt to mediate; a surrogate generally cannot override a specific prior refusal by a competent patient", "Refuse and walk away", "None of the above"]', 1, 'A valid refusal of treatment (DNI) should be honored, even over surrogate objection, though these are extremely difficult cases.'),
    (v_topic_id, 'What is "Palliative Sedation"?', '["Using drugs to kill a patient", "The use of medications to reduce consciousness to relieve refractory suffering in terminal patients", "Giving a patient a nap", "None of the above"]', 1, 'It is ethically distinct from euthanasia because the *intent* is comfort, not death.'),
    (v_topic_id, 'Which of the following is an example of "Non-abandonment"?', '["Staying with the patient and family even when no more curative options exist", "Calling the patient once a year", "Never leaving the hospital", "None of the above"]', 0, 'Non-abandonment is a core virtue of the physician-patient relationship, especially at the end of life.'),
    (v_topic_id, 'A "Guardian ad litem" is:', '["A judge", "A court-appointed representative for a child or incapacitated person during a legal proceeding", "A type of insurance", "None of the above"]', 1, 'They ensure the patient''s interests are represented in court disputes.'),
    (v_topic_id, 'Which of the following is a "Red Flag" in surrogate decision-making?', '["Consistent decisions over time", "A sudden, radical change in the surrogate''s request that contradicts the patient''s lifelong values", "Talking to the chaplain", "None of the above"]', 1, 'Sudden shifts may indicate external pressure or emotional instability.'),
    (v_topic_id, 'What is "Substituted Judgment"?', '["The doctor substitutes their judgment", "The surrogate acts as they believe the patient would have acted", "The family votes", "None of the above"]', 1, 'This is the most common and ethically preferred standard for surrogates.'),
    (v_topic_id, 'Can a surrogate "Withdraw" life support in an emergency room?', '["Yes, if they have clear evidence of the patient''s wishes", "No, emergencies require everything to be done", "Only if the patient is dead", "None of the above"]', 0, 'If the surrogate is known and the wishes are clear, care can be withheld or withdrawn even in the ER.'),
    (v_topic_id, 'What is the role of the "Ethics Committee" in surrogacy?', '["To make the final legal decision", "To provide a neutral forum for discussion, mediation, and advice when consensus cannot be reached", "To fire the doctor", "None of the above"]', 1, 'Ethics committees are advisory, not usually decision-making bodies.'),
    (v_topic_id, 'Which of the following is TRUE regarding "Common-Law Spouses" as surrogates?', '["They are never recognized", "In states that recognize common-law marriage, they have the same rights as any other spouse", "They must have a child together", "None of the above"]', 1, 'Legal recognition varies significantly by jurisdiction.'),
    (v_topic_id, 'A "Health Care Proxy" is a:', '["Person", "Document", "Machine", "None of the above"]', 0, 'The term "Proxy" refers to the person appointed to make decisions.'),
    (v_topic_id, 'Which of the following is NOT a valid reason to remove a surrogate?', '["They are following the patient''s wishes", "They are clearly acting out of malice or self-interest", "They have lost capacity themselves", "None of the above"]', 0, 'Honoring the patient''s wishes is the surrogate''s primary job.'),
    (v_topic_id, 'What is "Bereavement"?', '["The state of having suffered a loss", "A type of medication", "A funeral home", "None of the above"]', 0, 'Bereavement is the period of mourning.'),
    (v_topic_id, 'A surrogate is "Overwhelmed" and cannot make a decision. The physician should:', '["Force them to decide", "Provide support, simplify the choices, and perhaps offer a recommendation based on the patient''s goals", "Pick someone else", "None of the above"]', 1, 'The "Shared Decision Making" model involves the physician helping carry the burden of the decision.'),
    (v_topic_id, 'Which of the following is a "Myth" about surrogacy?', '["Surrogates always know what the patient wants", "Surrogates are always family members", "Surrogates must be named in a document", "All of the above are myths"]', 3, 'Studies show that surrogates only correctly predict patient wishes about 68% of the time.')
